-- ShopWise : schéma de base de données (étude de cas BC04, Q2)
-- Généré à partir des entités JPA du projet edc4-shopwise (Product, Vente, LigneVente, Discount, User).
-- Dialecte : H2 / SQL standard (colonnes IDENTITY). Pour MariaDB, remplacer
-- "GENERATED BY DEFAULT AS IDENTITY" par "AUTO_INCREMENT".

DROP TABLE IF EXISTS LIGNE_VENTE;
DROP TABLE IF EXISTS VENTES;
DROP TABLE IF EXISTS PRODUCTS;
DROP TABLE IF EXISTS DISCOUNT;
DROP TABLE IF EXISTS APP_USERS;

-- Utilisateurs (authentification)
CREATE TABLE APP_USERS (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username  VARCHAR(50)  NOT NULL UNIQUE,
    password  VARCHAR(255) NOT NULL,          -- mot de passe haché (BCrypt)
    role      VARCHAR(20)  NOT NULL
);

-- Catalogue de produits (existant)
CREATE TABLE PRODUCTS (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100)   NOT NULL,
    description VARCHAR(500),
    price       DECIMAL(10, 2) NOT NULL,
    created_at  TIMESTAMP,
    updated_at  TIMESTAMP
);

-- Remises applicables à une vente
CREATE TABLE DISCOUNT (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reduce  REAL NOT NULL
);

-- Ventes (module Ventes)
CREATE TABLE VENTES (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    boutique_id      BIGINT  NOT NULL,
    discount_id      BIGINT,
    user_id          BIGINT,
    date_achat       DATE    NOT NULL,
    quantite_totale  INTEGER NOT NULL DEFAULT 0,
    total            INTEGER NOT NULL DEFAULT 0,
    prix             REAL    NOT NULL DEFAULT 0,
    CONSTRAINT fk_ventes_discount FOREIGN KEY (discount_id) REFERENCES DISCOUNT (id),
    CONSTRAINT fk_ventes_user     FOREIGN KEY (user_id)     REFERENCES APP_USERS (id)
);

-- Lignes d'une vente : une vente contient plusieurs lignes, chaque ligne vise un produit
CREATE TABLE LIGNE_VENTE (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vente_id          BIGINT  NOT NULL,
    product_id        BIGINT  NOT NULL,
    quantite_produit  INTEGER NOT NULL,
    prix              INTEGER NOT NULL,
    CONSTRAINT fk_ligne_vente   FOREIGN KEY (vente_id)   REFERENCES VENTES (id) ON DELETE CASCADE,
    CONSTRAINT fk_ligne_produit FOREIGN KEY (product_id) REFERENCES PRODUCTS (id)
);
